-- Postgres dialect of schema/0957_github_app.sql (issue #656, AC-10; kept in parity with the SQLite file by
-- TestSchemaParity_SQLiteAndPostgres). Neither table references another tenant table, so no composite foreign key is
-- needed. rls.sql is regenerated by `tessera admin gen-rls`.

-- +goose Up

CREATE TABLE github_app_settings (
  tenant_id TEXT NOT NULL PRIMARY KEY REFERENCES tenants (id),
  enabled BIGINT NOT NULL DEFAULT 0 CHECK (enabled IN (0, 1)),
  app_id TEXT NOT NULL DEFAULT '' CHECK (length(app_id) <= 20),
  installation_id BIGINT NOT NULL DEFAULT 0 CHECK (installation_id >= 0),
  repo TEXT NOT NULL DEFAULT '' CHECK (length(repo) <= 201),
  key_enc BYTEA,
  key_fingerprint TEXT NOT NULL DEFAULT '' CHECK (length(key_fingerprint) <= 64),
  key_set_at TEXT NOT NULL DEFAULT '',
  updated_by TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE github_pr_checks (
  tenant_id TEXT NOT NULL REFERENCES tenants (id),
  repo TEXT NOT NULL CHECK (length(repo) <= 201),
  pull_number BIGINT NOT NULL CHECK (pull_number >= 1),
  head_sha TEXT NOT NULL CHECK (length(head_sha) <= 64),
  check_run_id BIGINT NOT NULL DEFAULT 0,
  comment_id BIGINT NOT NULL DEFAULT 0,
  conclusion TEXT NOT NULL CHECK (conclusion IN ('success', 'failure', 'neutral')),
  diff_sha256 TEXT NOT NULL DEFAULT '',
  updated_at TEXT NOT NULL,
  PRIMARY KEY (tenant_id, repo, pull_number)
);
